export interface AppConfig {
  region: string;
  userPoolId: string;
  userPoolClientId: string;
  apiUrl: string;
  /** Local development only: skip Cognito and talk to `npm run dev:api`. */
  devMode?: boolean;
}

let loaded: AppConfig | null = null;

/** config.json is generated by Terraform and uploaded next to the site, so one build works anywhere. */
export async function loadConfig(): Promise<AppConfig> {
  const res = await fetch('/config.json', { cache: 'no-store' });
  const type = res.headers.get('content-type') ?? '';
  if (!res.ok || !type.includes('json')) {
    throw new Error(
      'Missing /config.json. Deploy with Terraform, or for local work run scripts/dev-config.sh (see README).',
    );
  }
  loaded = (await res.json()) as AppConfig;
  return loaded;
}

export function config(): AppConfig {
  if (!loaded) throw new Error('Config not loaded');
  return loaded;
}
